// Formulário visual de questões. Não recebe nem executa HTML fornecido pelo professor.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=(text,control)=>`<label>${text}${control}</label>`;
const input=(key,value='',type='text',extra='')=>`<input data-q="${key}" type="${type}" value="${esc(value)}" ${extra}>`;
const select=(key,values,value)=>`<select data-q="${key}">${values.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select>`;
const textarea=(key,value='',extra='')=>`<textarea data-q="${key}" rows="4" ${extra}>${esc(value)}</textarea>`;
export function questionForm(q,number){return `<fieldset class="question-editor" data-question-id="${esc(q.id)}"><legend>Questão <span data-question-number>${number}</span></legend><div class="question-tools"><button type="button" data-action="up" class="outline">↑ Subir questão</button><button type="button" data-action="down" class="outline">↓ Descer questão</button><button type="button" data-action="remove" class="outline">Remover questão</button></div>${label('Tipo de questão',select('type',[['choice','Uma alternativa correta'],['multiple','Várias alternativas corretas'],['open','Resposta aberta'],['blanks','Preencher lacunas']],q.type||'choice'))}${label('Enunciado',textarea('prompt',q.prompt||'','maxlength="20000"'))}${label('Valor / peso da questão',input('points',q.points??1,'number','min="0.01" step="0.01"'))}<div data-answer-fields></div><details class="question-code-settings"><summary>Adicionar código de programação ao enunciado</summary>${label('Linguagem (opcional)',input('language',q.language||'','text','maxlength="40"'))}${label('Código-fonte',textarea('code',q.code||'','maxlength="20000" spellcheck="false" class="code-input"'))}</details></fieldset>`;}
export function answerFields(q){if(['choice','multiple'].includes(q.type))return `<p>${q.type==='choice'?'Marque a única resposta correta.':'Marque pelo menos duas respostas corretas. Omissões e marcações erradas descontam pontos, até o mínimo zero.'}</p><div data-options>${(q.options?.length?q.options:['','']).map((v,i)=>optionRow(q,v,i)).join('')}</div><button type="button" data-action="add-option" class="outline">Adicionar alternativa</button>`;
 if(q.type==='open')return label('Formato da resposta',select('responseFormat',[['text','Texto'],['code','Código de programação']],q.responseFormat||'text'))+'<p>A correção e o feedback serão feitos pelo professor após a entrega.</p>';
 return `<p>No enunciado, escreva <strong>{{1}}</strong>, <strong>{{2}}</strong> e assim por diante nos locais das lacunas. Depois preencha as respostas abaixo. Para aceitar variações, separe-as por ponto e vírgula.</p><button type="button" data-action="sync-blanks" class="outline">Atualizar lacunas do enunciado</button><div data-blanks>${(q.blanks||[]).map((b,i)=>label(`Respostas aceitas para a lacuna ${i+1}`,`<input data-blank="${i}" value="${esc((b.accepted||[]).join('; '))}">`)).join('')}</div><label><input data-q="ignoreCase" type="checkbox" ${q.ignoreCase!==false?'checked':''}> Aceitar maiúsculas/minúsculas como equivalentes</label><label><input data-q="ignoreAccents" type="checkbox" ${q.ignoreAccents!==false?'checked':''}> Aceitar respostas sem acentos</label>`;}
export function optionRow(q,value,index){return `<div class="option-editor" data-option><label><input data-correct type="${q.type==='multiple'?'checkbox':'radio'}" name="correct-${esc(q.id)}" ${(q.type==='multiple'?q.corrects?.includes(index):q.correct===index)?'checked':''}> Correta</label><label>Alternativa <input data-option-text value="${esc(value)}" maxlength="2000"></label><button type="button" data-action="remove-option" class="outline">Remover</button></div>`;}
export function readQuestionForm(root,typeOverride){const get=k=>root.querySelector(`[data-q="${k}"]`),type=typeOverride||get('type').value;const q={id:root.dataset.questionId,type,prompt:get('prompt').value.trim(),points:Number(get('points').value)};const code=get('code').value;if(code.trim()){q.code=code;q.language=get('language').value.trim();}
 if(['choice','multiple'].includes(type)){const rows=[...root.querySelectorAll('[data-option]')];q.options=rows.map(row=>row.querySelector('[data-option-text]').value.trim());const marked=rows.flatMap((row,i)=>row.querySelector('[data-correct]').checked?[i]:[]);if(type==='choice')q.correct=marked.length===1?marked[0]:-1;else q.corrects=marked;}
 else if(type==='open')q.responseFormat=get('responseFormat').value;
 else {q.ignoreCase=get('ignoreCase').checked;q.ignoreAccents=get('ignoreAccents').checked;q.blanks=[...root.querySelectorAll('[data-blank]')].map(el=>({accepted:el.value.split(';').map(s=>s.trim()).filter(Boolean)}));}return q;}
export function mountQuestionEditor(container,questions,{onError=console.error}={}){
 const originals=new Map(questions.map(q=>[q.id,q]));
 const renumber=()=>{[...container.children].forEach((root,i)=>{root.querySelector('[data-question-number]').textContent=i+1;root.querySelector('[data-action="up"]').disabled=i===0;root.querySelector('[data-action="down"]').disabled=i===container.children.length-1;});};
 const append=(q={id:crypto.randomUUID(),type:'choice',points:1,prompt:'',options:['',''],correct:-1})=>{const holder=document.createElement('div');holder.innerHTML=questionForm(q,container.children.length+1);const root=holder.firstElementChild;container.appendChild(root);root.dataset.currentType=q.type;const answers=root.querySelector('[data-answer-fields]');answers.innerHTML=answerFields(q);root.querySelector('[data-q="type"]').onchange=()=>{try{const previous=readQuestionForm(root,root.dataset.currentType),type=root.querySelector('[data-q="type"]').value;root.dataset.currentType=type;answers.innerHTML=answerFields({...previous,id:root.dataset.questionId,type});}catch(e){onError(e);}};
 root.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;try{if(action==='remove'){root.remove();renumber();}if(action==='up'&&root.previousElementSibling){container.insertBefore(root,root.previousElementSibling);renumber();}if(action==='down'&&root.nextElementSibling){container.insertBefore(root.nextElementSibling,root);renumber();}if(action==='add-option'){const options=answers.querySelector('[data-options]');if(options.children.length>=6)throw Error('Use até seis alternativas.');options.insertAdjacentHTML('beforeend',optionRow({id:root.dataset.questionId,type:root.dataset.currentType},'',options.children.length));}if(action==='remove-option'){const row=event.target.closest('[data-option]');if(row.parentElement.children.length<=2)throw Error('Mantenha pelo menos duas alternativas.');row.remove();}if(action==='sync-blanks'){const prompt=root.querySelector('[data-q="prompt"]').value,ids=[...prompt.matchAll(/\{\{(\d+)\}\}/g)].map(x=>Number(x[1]));if(!ids.length||ids.some((n,i)=>n!==i+1)||ids.length>20)throw Error('Use {{1}}, {{2}} e assim por diante, uma vez cada, em ordem. Até vinte lacunas.');const old=[...answers.querySelectorAll('[data-blank]')].map(el=>el.value);answers.querySelector('[data-blanks]').innerHTML=ids.map((_,i)=>label(`Respostas aceitas para a lacuna ${i+1}`,`<input data-blank="${i}" value="${esc(old[i]||'')}">`)).join('');}}catch(e){onError(e);}});renumber();return root;};
 for(const q of questions)append(q);
 return {append,read(){return [...container.children].map(root=>{const {correct,corrects,blanks,ignoreCase,ignoreAccents,responseFormat,options,code,language,...common}=originals.get(root.dataset.questionId)||{};return {...common,...readQuestionForm(root)};});}};
}
